onRoleReachedMoon = function()     game.pauseLogic()	if global.getBool("lvl55_b1") then dialog.setSkipEnabled(true) end		repeat			sound.play("58-1");		    if dialog.show("Level55-1", faceDeyi) ==1 then break end			sound.play("61-1");			if dialog.show("Level55-2", faceBujie) ==1 then break end			if dialog.show("Level55-3", faceZhoumei) ==1 then break end			if dialog.show("Level55-4", facePutong) ==1 then break end		    if dialog.show("Level55-5", facePutong) ==1 then break end			if dialog.show("Level55-6", faceZhoumei) ==1 then break end			sound.play("60-2");			if dialog.show("Level55-7", facePutong) ==1 then break end			global.setBool("lvl55_b1")		until true		dialog.setSkipEnabled(false)    game.success()end